export class DndState {
    active = $state(false);
    cardId = $state(null);
    sourceColumn = $state(null);
    width = $state(0);
    height = $state(0);
    pointer = $state({ x: 0, y: 0 });
    offset = $state({ x: 0, y: 0 });
    target = $state(null);
    reset() {
        this.active = false;
        this.cardId = null;
        this.sourceColumn = null;
        this.target = null;
    }
}
