export function getCardShape() {
    return {
        priority: true,
        progress: true,
        description: true,
        deadline: true,
        tags: true,
    };
}
export function getPriorityOptions() {
    return [
        { id: 1, label: "Low", css: "wx-card-priority-low" },
        { id: 2, label: "Medium", css: "wx-card-priority-medium" },
        { id: 3, label: "High", css: "wx-card-priority-high" },
    ];
}
function configOf(shape) {
    return typeof shape === "object" && shape !== null ? shape : undefined;
}
export function getEditorItems(shape) {
    const s = shape ?? {
        description: true,
        priority: true,
        progress: true,
        deadline: true,
        tags: false,
        users: false,
    };
    const items = [
        { comp: "text", key: "label", label: "Title", required: true },
    ];
    if (s.description) {
        items.push({
            comp: "textarea",
            key: "description",
            label: "Description",
        });
    }
    if (s.priority) {
        const priorityData = configOf(s.priority)?.data;
        items.push({
            comp: "richselect",
            key: "priority",
            label: "Priority",
            options: priorityData ?? getPriorityOptions(),
        });
    }
    if (s.progress) {
        items.push({
            comp: "slider",
            key: "progress",
            label: "Progress",
            min: 0,
            max: 1,
            step: 0.1,
        });
    }
    if (s.deadline) {
        items.push({
            comp: "datepicker",
            key: "deadline",
            label: "Deadline",
            clear: true,
        });
    }
    const tagsData = configOf(s.tags)?.data;
    if (tagsData) {
        items.push({
            comp: "multicombo",
            key: "tags",
            label: "Tags",
            options: tagsData,
        });
    }
    const usersData = configOf(s.users)?.data;
    if (usersData) {
        items.push({
            comp: "multicombo",
            key: "users",
            label: "Users",
            options: usersData,
        });
    }
    return items;
}
